import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.qcK96eCy.js";var i=JSON.parse(`{"title":"Environment variables","description":"","frontmatter":{},"headers":[],"relativePath":"reference/environment.md","filePath":"reference/environment.md","lastUpdated":1788348328000}`),a={name:`reference/environment.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="environment-variables" tabindex="-1">Environment variables <a class="header-anchor" href="#environment-variables" aria-label="Permalink to “Environment variables”">​</a></h1><p>The complete set. There is no config file and no command-line flag.</p><h2 id="audiobookshelf-url" tabindex="-1"><code>AUDIOBOOKSHELF_URL</code> <a class="header-anchor" href="#audiobookshelf-url" aria-label="Permalink to “AUDIOBOOKSHELF_URL”">​</a></h2><p><strong>Required.</strong> Base URL of the Audiobookshelf instance, e.g. <code>https://abs.example.com</code>.</p><table tabindex="0"><thead><tr><th>Rule</th><th>Behaviour</th></tr></thead><tbody><tr><td>Unparseable by <code>new URL()</code></td><td>Server exits with an error</td></tr><tr><td>Scheme other than <code>http</code>/<code>https</code></td><td>Server exits with an error</td></tr><tr><td>Contains <code>user:pass@</code></td><td>Server exits with an error</td></tr><tr><td>Trailing slashes</td><td>Stripped</td></tr><tr><td>Plain <code>http</code> to a remote host</td><td>Warning on stderr, server continues</td></tr><tr><td>Plain <code>http</code> to loopback</td><td>No warning</td></tr></tbody></table><p>Loopback means <code>localhost</code>, <code>*.localhost</code>, <code>127.*</code> or <code>::1</code>.</p><h2 id="audiobookshelf-api-key" tabindex="-1"><code>AUDIOBOOKSHELF_API_KEY</code> <a class="header-anchor" href="#audiobookshelf-api-key" aria-label="Permalink to “AUDIOBOOKSHELF_API_KEY”">​</a></h2><p><strong>Required.</strong> Sent as <code>Authorization: Bearer &lt;key&gt;</code>. Created under <strong>Settings → Users → API Keys</strong> (admin only, Audiobookshelf 2.26.0 or newer) and shown once at creation.</p><p>Deleted from <code>process.env</code> after the configuration is read, so it is not visible to child processes or in <code>/proc/&lt;pid&gt;/environ</code>.</p><p>Missing credentials are not fatal: the server starts, completes the handshake and lists all 44 tools, and every call then fails with the setup instructions.</p><h2 id="audiobookshelf-read-only" tabindex="-1"><code>AUDIOBOOKSHELF_READ_ONLY</code> <a class="header-anchor" href="#audiobookshelf-read-only" aria-label="Permalink to “AUDIOBOOKSHELF_READ_ONLY”">​</a></h2><p><strong>Optional</strong>, default <code>false</code>. Exactly the string <code>true</code> enables it — <code>1</code>, <code>yes</code> and <code>TRUE</code> do not, and the difference fails open, with the write tools registered. The server logs the active setting at startup.</p><p>When enabled, the 15 write tools are never registered; <code>tools/list</code> returns 29.</p><h2 id="audiobookshelf-insecure-tls" tabindex="-1"><code>AUDIOBOOKSHELF_INSECURE_TLS</code> <a class="header-anchor" href="#audiobookshelf-insecure-tls" aria-label="Permalink to “AUDIOBOOKSHELF_INSECURE_TLS”">​</a></h2><p><strong>Optional</strong>, default <code>false</code>. Exactly the string <code>true</code> enables it.</p><p>Accepts self-signed and untrusted certificates <strong>for the Audiobookshelf connection only</strong>, via a scoped undici dispatcher. It does not set <code>NODE_TLS_REJECT_UNAUTHORIZED</code> and does not affect any other request the process makes. A warning is printed to stderr while it is active.</p><p>Prefer adding your CA to the system trust store.</p><h2 id="elicitation" tabindex="-1"><code>ELICITATION</code> <a class="header-anchor" href="#elicitation" aria-label="Permalink to “ELICITATION”">​</a></h2><p><strong>Optional</strong>, default <code>true</code>. Whether a client that <em>can</em> show a dialog is asked before a guarded tool acts. <code>false</code> takes the two-call-token path instead — it does not remove the guard, and a server started with it off prints one line saying so.</p><p>Two ways it differs from every other variable on this page:</p><ul><li><strong>No prefix.</strong> One <code>export ELICITATION=false</code> reaches every MCP server in the same environment, not just this one. That is the point of it and also its risk; see <a href="/guide/approval">Asking a person</a>.</li><li><strong>Fatal on anything else.</strong> <code>1</code>, <code>off</code> or a typo stop the server with exit code 1 rather than falling back to the default. It is the only variable of this family that defaults to <em>on</em>, and a typo that fell back would leave the dialog running while you believed it was off.</li></ul><p>Values are trimmed and matched case-insensitively, so <code>False</code> and <code>false</code> both work — the strictness is about which words count, not about their shape. It is read <em>after</em> the API key is deleted from <code>process.env</code>, so the fatal path cannot leave the key sitting there for a crash reporter.</p><h2 id="not-configurable" tabindex="-1">Not configurable <a class="header-anchor" href="#not-configurable" aria-label="Permalink to “Not configurable”">​</a></h2><table tabindex="0"><thead><tr><th>Behaviour</th><th>Value</th></tr></thead><tbody><tr><td>Request timeout</td><td>15 s</td></tr><tr><td>HTTP redirects</td><td>never followed</td></tr><tr><td>Response ceiling</td><td>5 MB</td></tr><tr><td>Result ceiling</td><td>100 000 bytes</td></tr><tr><td>Item-page cap</td><td>100 entries</td></tr><tr><td>Embedded members</td><td>first 25</td></tr><tr><td>Description cap</td><td>800 characters</td></tr><tr><td>Error body cap</td><td>2000 chars</td></tr><tr><td>Fallback token TTL</td><td>5 minutes</td></tr><tr><td>Pending tokens</td><td>max 100</td></tr></tbody></table><h2 id="narrowing-the-tool-list" tabindex="-1">Narrowing the tool list <a class="header-anchor" href="#narrowing-the-tool-list" aria-label="Permalink to “Narrowing the tool list”">​</a></h2><table tabindex="0"><thead><tr><th>Variable</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>AUDIOBOOKSHELF_ALLOW_TOOLS</code></td><td>no</td><td>Tool names, <code>list_*</code> prefixes or <code>essential</code>; only these register</td></tr><tr><td><code>AUDIOBOOKSHELF_DENY_TOOLS</code></td><td>no</td><td>Same syntax; subtracted from whatever the allow list left</td></tr></tbody></table><p>Both are comma-separated. Each entry is either an exact tool name or a prefix with a single trailing <code>*</code>. Entries are trimmed and matched case-insensitively; empty entries are ignored, and a value that is empty or only whitespace counts as unset — <code>AUDIOBOOKSHELF_ALLOW_TOOLS=</code> in a compose file does not mean &quot;allow nothing&quot;. <code>essential</code> is recognised only in the allow list, and selects <code>list_libraries</code>, <code>search_library</code>, <code>list_library_items</code>, <code>get_library_item</code>, <code>get_item_chapters</code>, <code>list_items_in_progress</code>, <code>get_media_progress</code>, <code>set_media_progress</code>.</p><p><strong>An entry that matches no tool aborts startup</strong>, naming the entry and listing the valid names, as does a malformed pattern such as <code>*_x</code> or <code>list_*_x</code>. The alternative — ignoring the entry — leaves a tool missing from <code>tools/list</code> with nothing pointing at the cause. If both lists together remove everything, the server refuses to start rather than offering an empty tool list.</p><p>Under <code>AUDIOBOOKSHELF_READ_ONLY</code>, an exact write-tool name in the allow list is an error naming the read-only setting rather than &quot;unknown tool&quot;; a pattern covering write tools is accepted and merely contributes nothing, with a warning on stderr. Deny entries are exempt: denying an already-suppressed tool is how a defensive list is written.</p>`,29)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};